INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷113·太祖本纪四·郭威遗命与去世", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/3ba4c15f89bc0e4a416ae35be0615a8c443b7f49/content/books/zizhi-tongjian/vol-291/year-0954/part-01/sources/library/jiuwudaishi-113-guowei-death-954/source.txt", "note": "《旧五代史》卷113·太祖本纪四·郭威遗命与去世，段落 jiu-wudaishi-205deb4a7860-p002697；已核上下文及传主，纸本及异文待核。", "id": "8b676135-5b3c-5a13-8fc2-50ba23eae94c"}, {"title": "旧五代史·卷113·太祖本纪四·显德元年正月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/3ba4c15f89bc0e4a416ae35be0615a8c443b7f49/content/books/zizhi-tongjian/vol-291/year-0954/part-01/sources/library/jiuwudaishi-113-january-954/source.txt", "note": "《旧五代史》卷113·太祖本纪四·显德元年正月，段落 jiu-wudaishi-205deb4a7860-p002696；已核上下文及传主，纸本及异文待核。", "id": "e4d85411-42fc-538a-991d-bc31cd960527"}, {"title": "旧五代史·卷114·世宗本纪一·柴荣即位", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/3ba4c15f89bc0e4a416ae35be0615a8c443b7f49/content/books/zizhi-tongjian/vol-291/year-0954/part-01/sources/library/jiuwudaishi-114-chairong-accession/source.txt", "note": "《旧五代史》卷114·世宗本纪一·柴荣即位，段落 jiu-wudaishi-205deb4a7860-p002704；已核上下文及传主，纸本及异文待核。", "id": "ae04b0b5-425f-52df-9708-bd61f4a72c55"}, {"title": "宋史·卷260·曹翰传早年", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/3ba4c15f89bc0e4a416ae35be0615a8c443b7f49/content/books/zizhi-tongjian/vol-291/year-0954/part-01/sources/library/songshi-260-caohan-early/source.txt", "note": "《宋史》卷260·曹翰传早年，段落 songshi-9c6e46fee832-p057945；已核上下文及传主，纸本及异文待核。", "id": "a03a0b0d-334f-533b-afa3-d0a3005c53c1"}, {"title": "新五代史·卷12·周本纪第十二·柴荣即位", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/3ba4c15f89bc0e4a416ae35be0615a8c443b7f49/content/books/zizhi-tongjian/vol-291/year-0954/part-01/sources/library/xinwudaishi-12-chairong-accession/source.txt", "note": "《新五代史》卷12·周本纪第十二·柴荣即位，段落 xin-wudaishi-b08f244b9241-p000376；已核上下文及传主，纸本及异文待核。", "id": "e8e8d8ba-d759-5bf8-896c-ca674bd3a93d"}, {"title": "资治通鉴·卷291·广顺三年末至显德元年初及年界", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/1df54f287032ffe638308d6b8b6efe6b4bf86b76/content/books/zizhi-tongjian/vol-291/year-0953/part-05/sources/library/tongjian-291-953-end-954-opening/source.txt", "note": "《资治通鉴》卷291·广顺三年末至显德元年初及年界，段落 zizhi-tongjian-a63549944a71-p003459；已核上下文及传主，纸本及异文待核。", "id": "9578cbb6-a420-59ef-b7b1-f00bdac11d46"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "曹翰", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "大名人，曾为郡中小吏，受郭威知遇后随柴荣，任澶州牙将。郭威病中，劝柴荣入宫侍疾，《宋史》还记柴荣让他总理府务。生卒年暂未核定。", "biography": null, "status": "draft", "id": "9c79672a-4f9e-5a5f-8dfb-9360586d8ee8"}, {"name": "郑仁诲", "aliases": ["鄭仁誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "晋阳人，后周内客省使、恩州团练使。952年三月任枢密副使，新旧五代史同日记载。生卒年尚未录入。", "biography": null, "status": "draft", "id": "f7eb66ac-1c5c-5720-aa2e-9256e75c2b71"}, {"name": "孙行友", "aliases": ["孫行友"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "与孙方简聚众于狼山，借孙深意的术及边民避乱扩展部众。《宋史》记为莫州清苑人，出身务农，后任孙方谏的副手；《资治通鉴》记为孙方简之弟，《宋史》却记孙方谏为他的兄子，亲属与籍贯表述分别保留待核。生卒年未核。", "biography": null, "status": "draft", "id": "297fda14-1470-5546-b76b-7b2461eb1d3d"}, {"name": "韩通", "aliases": ["韓通"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，后周保义军留后。954年正月正式任保义节度使，《旧五代史》以陕州留后称其前职。生卒年暂未核定。", "biography": null, "status": "draft", "id": "81e4d74c-3057-59e4-a9a3-5baa18bff059"}, {"name": "冯继业", "aliases": ["馮繼業"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "大名人，字嗣宗，冯晖之子、冯继勋的弟弟。952年父亲去世前后杀兄，自掌朔方军府，六月获后周授朔方留后。《宋史》安排谋杀在父病时，时序独立保留。生卒年未录全。", "biography": null, "status": "draft", "id": "a653d65a-339b-5df1-99c3-a27f7671128d"}, {"name": "李洪义", "aliases": ["李洪義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉李太后的弟弟，950年任镇宁节度使。刘承祐下密诏令他杀驻澶州的王殷，本段只记命令，未记他已经执行。生卒年未载。", "biography": null, "status": "draft", "id": "12dc9c88-13ce-589c-94c7-384ae0bd7223"}, {"name": "魏仁浦", "aliases": ["魏仁溥"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "字道济，卫州汲人。后晋末任枢密院小吏，随众被迁往契丹后逃归。947年在巩县迎见刘知远，因熟知军队人数与旧制受到郭威信任。生卒年尚未录入。", "biography": null, "status": "draft", "id": "c2e87754-6e6a-56db-b3e1-45835b2bff92"}, {"name": "周训", "aliases": ["周訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "前登州刺史。954年正月受命与其他使者处理黄河八处决口。生卒年未载。", "biography": null, "status": "draft", "id": "59bf65ea-dc15-53f4-bde8-2a8577c52e0d"}, {"name": "王溥（后周宋初）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "949年为秘书郎，在河中平定后劝郭威焚毁涉及朝臣、藩镇的往来书信，《宋史》王溥传也记此事。与901年条所载同名王溥分开建档。生卒年留待具体原文补录。", "biography": null, "status": "draft", "id": "13d3b7ec-869a-5019-ac41-39e5abcd2df3"}, {"name": "王仁镐", "aliases": ["王仁鎬"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成二年条所见人物：王仁镐，供奉官、报告所指称制执行者。", "biography": null, "status": "draft", "id": "3b630a2d-5a16-50b8-b441-93eebb35e76f"}, {"name": "李重进", "aliases": ["李重進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "沧州人，福庆长公主之子，郭威的外甥，生于太原。郭威在藩镇时期的将佐，952年任恩州团练使，逐渐受重用。《宋史》还记当年内殿职务变化，具体任日未载。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9769d0fb-1d80-593e-9aa3-e4c22416f835"}, {"name": "樊爱能", "aliases": ["樊愛能"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周马军将领。954年正月获领武定节度使，旧纪同时记其军职与洋州节度职衔。生卒年暂未核定。", "biography": null, "status": "draft", "id": "31b12a36-803d-574a-a818-05742d936537"}, {"name": "何徽", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周虎捷指挥使。951年与王万敢、史彦超共同抵御北汉、契丹对晋州的进攻。生卒年未载。", "biography": null, "status": "draft", "id": "2982109b-18cc-561f-9927-a98ba7b7f5e6"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
